files.content:
:root {
  --bg: #1e1b2e;
  --panel: #2b2740;
  --card-back: #3d3757;
  --accent: #f4a261;
  --text: #f5f2ff;
  --muted: #b7b0d0;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at 50% 0%, #322c4a 0%, var(--bg) 70%);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  padding: 24px 16px;
}

.app {
  width: 100%;
  max-width: 520px;
  background: var(--panel);
  border-radius: 20px;
  padding: 28px 24px 32px;
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.45);
}

.app__header {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px 16px;
  margin-bottom: 24px;
}

.app__title {
  margin: 0;
  font-size: 1.5rem;
  letter-spacing: 0.02em;
}

.app__moves {
  margin: 0;
  font-size: 1rem;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

.app__moves span {
  color: var(--accent);
  font-weight: 700;
}

.board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.card {
  position: relative;
  aspect-ratio: 1 / 1;
  border: none;
  border-radius: 12px;
  background: var(--card-back);
  cursor: pointer;
  padding: 0;
  transition: transform 0.12s ease, box-shadow 0.12s ease, background 0.12s ease;
}

.card::after {
  content: "?";
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--muted);
  opacity: 1;
  transition: opacity 0.12s ease;
}

.card.is-flipped,
.card.is-matched {
  background: var(--face, var(--accent));
  box-shadow: inset 0 0 0 3px rgba(255, 255, 255, 0.25);
}

.card.is-flipped::after,
.card.is-matched::after {
  opacity: 0;
}

.card.is-matched {
  cursor: default;
  opacity: 0.85;
}

.card:hover:not(.is-matched):not(.is-flipped) {
  transform: translateY(-3px);
  box-shadow: 0 8px 18px rgba(0, 0, 0, 0.4);
}

.card:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.card:active:not(.is-matched):not(.is-flipped) {
  transform: scale(0.96);
}

.win-message {
  margin: 24px 0 0;
  padding: 16px;
  text-align: center;
  font-size: 1.15rem;
  font-weight: 700;
  color: #1e1b2e;
  background: var(--accent);
  border-radius: 12px;
}

.app__actions {
  margin-top: 24px;
  display: flex;
  justify-content: center;
}

.btn {
  font: inherit;
  font-weight: 700;
  font-size: 1rem;
  color: #1e1b2e;
  background: var(--accent);
  border: none;
  border-radius: 999px;
  padding: 14px 32px;
  cursor: pointer;
  transition: transform 0.12s ease, filter 0.12s ease;
}

.btn:hover {
  filter: brightness(1.08);
  transform: translateY(-2px);
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 3px;
}

.btn:active {
  transform: scale(0.97);
}

@media (max-width: 380px) {
  .board {
    gap: 8px;
  }
  .app {
    padding: 22px 16px 26px;
  }
  .app__title {
    font-size: 1.3rem;
  }
}

(function () {
  "use strict";

  var COLORS = [
    "#e76f51", "#f4a261", "#e9c46a", "#2a9d8f",
    "#264653", "#8e7dbe", "#f28482", "#84a59d"
  ];

  var board = document.getElementById("board");
  var movesEl = document.getElementById("moves");
  var winEl = document.getElementById("win-message");
  var newGameBtn = document.getElementById("new-game");

  var firstCard = null;
  var lockBoard = false;
  var moves = 0;
  var matchedPairs = 0;

  function shuffle(arr) {
    for (var i = arr.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var tmp = arr[i];
      arr[i] = arr[j];
      arr[j] = tmp;
    }
    return arr;
  }

  function buildDeck() {
    var deck = [];
    COLORS.forEach(function (color, index) {
      deck.push({ color: color, pair: index });
      deck.push({ color: color, pair: index });
    });
    return shuffle(deck);
  }

  function setMoves() {
    movesEl.textContent = String(moves);
  }

  function resetState() {
    firstCard = null;
    lockBoard = false;
    moves = 0;
    matchedPairs = 0;
    setMoves();
    winEl.hidden = true;
    winEl.textContent = "";
  }

  function onCardClick(event) {
    var card = event.currentTarget;
    if (lockBoard || card === firstCard) return;
    if (card.classList.contains("is-flipped") || card.classList.contains("is-matched")) return;

    card.classList.add("is-flipped");
    card.setAttribute("aria-pressed", "true");

    if (!firstCard) {
      firstCard = card;
      return;
    }

    moves += 1;
    setMoves();
    lockBoard = true;

    var secondCard = card;
    var isMatch = firstCard.dataset.pair === secondCard.dataset.pair;

    if (isMatch) {
      firstCard.classList.add("is-matched");
      secondCard.classList.add("is-matched");
      firstCard.disabled = true;
      secondCard.disabled = true;
      firstCard = null;
      lockBoard = false;
      matchedPairs += 1;
      if (matchedPairs === COLORS.length) {
        winEl.textContent = "You win! Completed in " + moves + " moves.";
        winEl.hidden = false;
      }
    } else {
      window.setTimeout(function () {
        firstCard.classList.remove("is-flipped");
        secondCard.classList.remove("is-flipped");
        firstCard.setAttribute("aria-pressed", "false");
        secondCard.setAttribute("aria-pressed", "false");
        firstCard = null;
        lockBoard = false;
      }, 750);
    }
  }

  function render() {
    board.innerHTML = "";
    var deck = buildDeck();

    deck.forEach(function (item, index) {
      var card = document.createElement("button");
      card.type = "button";
      card.className = "card";
      card.dataset.pair = String(item.pair);
      card.style.setProperty("--face", item.color);
      card.setAttribute("aria-pressed", "false");
      card.setAttribute("aria-label", "Card " + (index + 1) + ", hidden");
      card.addEventListener("click", onCardClick);
      board.appendChild(card);
    });
  }

  function newGame() {
    resetState();
    render();
  }

  newGameBtn.addEventListener("click", newGame);
  newGame();
})();
